-- public.move_creator_market
-- Generated by scripts/schema-snapshot.mjs from project heuhqqoxyggawuckxocp. Do not edit by hand.

-- SECURITY DEFINER; API roles that may call it: service_role
CREATE OR REPLACE FUNCTION public.move_creator_market(p_profile uuid, p_from uuid, p_to uuid, p_make_home boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_was_home boolean;
begin
  if not public.is_global_admin() then
    raise exception 'Only the Tryp.com team can move creators between markets';
  end if;
  if p_from = p_to then return; end if;
  if not exists (select 1 from public.communities where id = p_to and kind = 'chapter') then
    raise exception 'No such market';
  end if;

  select is_home into v_was_home
  from public.community_members where community_id = p_from and profile_id = p_profile;

  delete from public.community_members
   where community_id = p_from and profile_id = p_profile;

  insert into public.community_members (community_id, profile_id, role, is_home, status)
  values (p_to, p_profile, 'creator', coalesce(p_make_home, v_was_home, false), 'active')
  on conflict (community_id, profile_id) do update
    set status = 'active',
        is_home = public.community_members.is_home or coalesce(p_make_home, v_was_home, false);

  insert into public.admin_audit_log (actor_id, actor_name, action, target_id, target_name)
  select auth.uid(), (select name from public.profiles where id = auth.uid()),
         'Moved creator between markets', p_profile,
         (select name from public.profiles where id = p_profile);
end;
$function$;
